"""Request and response schemas for the inference API."""

from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field


class ToxicityEvidence(BaseModel):
    """One cited reference record backing a toxicity lookup."""

    source_id: str
    source_match: str
    evidence_taxon: str
    evidence_status: str
    match_scope: str
    source_url: str


class ToxicityResult(BaseModel):
    """Source-backed toxicity status matched from the local JSON, not generated by Spark."""

    toxicity_status: Literal["toxic", "non_toxic", "unknown"]
    potential_hazard: bool | None
    matched_class: str | None = None
    scientific_name: str | None = None
    taxonomic_scope: str | None = None
    evidence: list[ToxicityEvidence] = Field(default_factory=list)
    lookup_note: str | None = None


class PlantAssessment(BaseModel):
    """Structured visual assessment returned by Muse Spark plus local lookup."""

    model_config = ConfigDict(extra="forbid")

    plant_identification: str
    identification_confidence: Literal["high", "medium", "low"]
    flower_count_estimate: int = Field(ge=0)
    flower_count_confidence: Literal["high", "medium", "low"]
    flower_count_notes: str
    suggest_segmentation: bool
    segmentation_reason: str
    visual_evidence: list[str]
    toxicity: ToxicityResult | None = None
    raw_meta_response: dict[str, Any] | None = None


class ClassScore(BaseModel):
    """One class prediction and its uncalibrated head probability."""

    class_name: str
    probability: float = Field(ge=0, le=1)


class TrainedPrediction(BaseModel):
    """Prediction from one saved notebook 03 classifier head."""

    model_name: str
    predicted_class: str
    confidence: float = Field(ge=0, le=1)
    confidence_is_calibrated: Literal[False] = False
    top_predictions: list[ClassScore]
    toxicity: ToxicityResult | None = None


class SegmentAssessment(BaseModel):
    """SAM segment plus its optional Muse Spark re-assessment."""

    object_id: str
    bounds: tuple[int, int, int, int]
    crop_data_url: str
    assessment: PlantAssessment
    in_trained_taxonomy: bool


class SegmentationResult(BaseModel):
    """Conditional SAM result for the uploaded image."""

    ran: bool
    status: Literal["skipped", "completed", "no_masks", "failed"]
    reason: list[str]
    prompt: str | None = None
    segments: list[SegmentAssessment] = Field(default_factory=list)
    error: str | None = None


class CompareResponse(BaseModel):
    """Side-by-side response for both user-visible analysis flows."""

    trained_flow: TrainedPrediction
    muse_spark_flow: PlantAssessment
    segmentation: SegmentationResult
    image_width: int
    image_height: int
